powerpagecomponent.content:
{
  "source": "{% include 'Wrapper Ajax Template' %}
{% block main %}
{% include 'QSPasswordEncryption' %}
{% editable page 'adx_copy' type: 'html', liquid: true %}

{% if request.params['contactid'] %}
{% assign contactid = request.params['contactid'] %}
{% assign contact = entities['contact'][contactid] %}
{% assign contactEmail = contact.emailaddress1 %}
{% endif %}

<style>
  .tab {
    overflow: hidden;
    border: 1px solid #ccc;
    background-color: #f1f1f1;
  }

  .resetCode,
  .newPassword,
  .confirmPassword {
    margin-right: 25px;
  }

  .tab button {
    background-color: inherit;
    float: left;
    border: none;
    outline: none;
    cursor: pointer;
    padding: 14px 16px;
    transition: 0.3s;
    font-size: 17px;
  }

  .tab button:hover {
    background-color: #ddd;
  }

  .tab button.active {
    background-color: #ccc;
    color: #006680;
  }

  .tabcontent {
    display: none;
    padding: 40px 75px;
    border: 1px solid #ccc;
  }

  .userInfo {
    margin-top: 20px;
  }

  #resetPasswordButton {
    border-color: #006680;
    border-radius: 2px;
    font-family: Arial;
    font-weight: 600;
    font-size: 14px;
    padding: 4px 15px;
    width: fit-content;
    border-style: solid;
    background-color: #006680;
    color: #FFFFFF;
  }

  input {
    padding: 6px 12px;
    width: 25%;
    border: 1px solid #949494;
  }

  button[disabled] {
    background-color: #F3F2F1 !important;
    color: #A19F9D !important;
    border: 2px !important;
    cursor: not-allowed !important;
    pointer-events: auto !important;
  }

  @media only screen and (max-width: 600px) {
    .userInfo {
      display: flex;
      flex-direction: column;
    }

    input {
      width: auto;
    }
  }
</style>

<div id="content-container" class="container" role="main">
  <div id="content">
    <div id="ResetPassword" class="tabcontent" style="display: block;">
      <div class="userInfo">
        <label class="resetCode" for="resetCode">Reset Code</label>
        <input type="text" id="resetCode" name="resetCode" placeholder="Enter your reset code" autocomplete="off" required><br>
      </div>
      <div class="userInfo">
        <label class="newPassword" for="newPassword">New Password</label>
        <input type="password" id="newPassword" name="newPassword" placeholder="Enter new password" autocomplete="off" required><br>
      </div>
      <div class="userInfo">
        <label class="confirmPassword" for="confirmPassword">Confirm Password</label>
        <input type="password" id="confirmPassword" name="confirmPassword" placeholder="Confirm new password" autocomplete="off" required><br>
      </div>
      <div class="userInfo">
        <button id="resetPasswordButton" type="button">Reset Password</button>
      </div>
    </div>
  </div>
</div>

<script type="text/javascript">
     $(document).ready(function () {

        var contactid = "{{ contactid }}";
        var contactEmail = "{{ contactEmail }}";

        $('#resetPasswordButton').click(function () {
            var $this = $(this);
            var resetCode = $('#resetCode').val();
            var newPassword = $('#newPassword').val();
            var confirmPassword = $('#confirmPassword').val();

            if (newPassword !== confirmPassword) {
            alert('Passwords do not match.');
            return;
            }
            $this.prop('disabled', true).text('Processing...');
            window.hashPassword(newPassword).then(hashedPassword => {
              resetPassword(resetCode, hashedPassword, contactid, contactEmail);
            });
        });

        function resetPassword(resetCode, newPassword, contactid, contactEmail) {
            var currentPageUrl = window.location.href;
            var baseUrl = currentPageUrl.split('/').slice(0, 3).join('/');
            //reset password request
            var relativePath = "_api/cloudflow/v1.0/trigger/216eb1fd-e186-e5d2-23ce-3f517d23a7bb";
            var flowUrl = baseUrl + "/" + relativePath;

            var flowData = {
                resetCode: resetCode,
                newPassword: newPassword,
                contactid: contactid,
                contactEmail: contactEmail
            };

            console.log("Sending Reset Password Request:", flowData);

            shell.ajaxSafePost({
            type: "POST",
            contentType: "application/json",
            url: flowUrl,
            data: JSON.stringify({ "eventData": JSON.stringify(flowData) }),
            processData: false,
            global: false
            })
            .done(function(response) {
            var result = JSON.parse(response);
            if (result.success) {
                alert('Password has been reset successfully.');
                window.location.href = '/qssignin';
            } else {
                alert(result.errormessage || 'Failed to reset password. Please try again.');
            }
            })
            .fail(function(error) {
            console.error('Error during reset password request:', error);
            alert('Error during reset password request.');
            });
        }
    });
</script>
{% endblock %}
"
}
